WITH latest AS (SELECT * FROM sessions QUALIFY ROW_NUMBER() OVER (PARTITION BY customer_id, browser ORDER BY started_at DESC NULLS LAST, id) = 1) SELECT s.id, s.customer_id, s.device, s.browser, s.started_at, s.country, CASE WHEN browser RLIKE '^(Chrome|Safari)$' THEN 'CORE' WHEN browser RLIKE '^(Firefox|Edge)$' THEN 'EXTENDED' ELSE 'GROUP_B' END AS browser_zone, (SELECT SUM(a2.balance) FROM accounts a2 WHERE a2.customer_id = s.customer_id) AS sum_account_balance FROM latest s ORDER BY browser DESC NULLS LAST
